/* Mise food diary and meals: diary with searchable food picker, recipes, saved recipes, weekly plan, meal prep, shopping. */
const CL=()=>S.lists.find(l=>l.id==li)||S.lists[0],nl=u=>{u=(u||"").trim();return u&&!/^https?:\/\//i.test(u)?"https://"+u:u};
function seedStarter(){const B=findMeals({t:"b"})[0],M=findMeals({t:"m"})[0];if(B)rcp(B.x);if(M)rcp(M.x)}
let fdte=TD(),pd=0,aiOut=null,aiR=[],ptab="plan";
const kc=(f,g)=>({k:f.k*g/100,p:f.p*g/100,c:f.c*g/100,f:f.f*g/100});
const MTN=Object.fromEntries(MT);

/* ======================= FOOD DIARY ======================= */
V.food=()=>{const d=fdte,t=tgt(),e=eaten(d),ent=S.flog[d]||[],left=t.k-e.k+burnOf(d);
 return `<div class="row nw tight"><button class="ibtn" onclick="fdte=dAdd(fdte,-1);go()" aria-label="Previous day">${ic("chevL")}</button><h2 class="grow tc">${d==TD()?"Today":d==dAdd(TD(),-1)?"Yesterday":fd(d)}</h2><button class="ibtn" onclick="fdte=dAdd(fdte,1);go()" ${d>=TD()?"disabled":""} aria-label="Next day">${ic("chevR")}</button></div>
 <div class="card gap"><div class="eq"><div><b>${t.k}</b><span>Goal</span></div><i>−</i><div><b>${R(e.k)}</b><span>Food</span></div><i>+</i><div><b>${R(burnOf(d))}</b><span>Exercise</span></div><i>=</i><div class="lf"><b style="${left<0?"color:var(--rd)":""}">${R(Math.abs(left))}</b><span>${left<0?"Over":"Left"}</span></div></div><div class="bar2 gap ${left<0?"over":""}"><div style="width:${Math.min(100,e.k/(t.k+burnOf(d))*100)}%"></div></div><div class="gap">${macBar("Protein",e.p,t.p,"var(--ac2)")}${macBar("Carbs",e.c,t.c,"var(--wa)")}${macBar("Fat",e.f,t.f,"#7b6cf6")}</div></div>
 <div class="qa" style="grid-template-columns:repeat(4,1fr)"><button onclick="openFoodSearch()">${ic("search",24)}Search food</button><button onclick="aiLogOpen()">${ic("mic",24)}Say or type it</button><button onclick="photoOpen()">${ic("camera",24)}Photo</button><button onclick="quickAdd()">${ic("plus",24)}Quick add</button></div>
 ${MT.map(m=>{const L=ent.filter(x=>x.mt==m[0]),kk=L.reduce((a,x)=>a+x.k,0);return `<div class="card"><div class="meal-h"><h3>${m[1]}</h3><span class="kc">${R(kk)} kcal</span><button class="ibtn sm soft" onclick="openFoodSearch('${m[0]}')" aria-label="Add food to ${m[1]}">${ic("plus",18)}</button></div>${L.map(x=>`<div class="item"><div class="tx"><div class="t">${x.s=="photo"?ic("camera",14)+" ":x.s=="assistant"?ic("sparkles",14)+" ":""}${esc(x.n)}</div><div class="s">P${x.p} · C${x.c} · F${x.f}</div></div><div class="r">${x.k}<span class="mut sm-t"> kcal</span></div><button class="ibtn sm ghost" onclick="delLog('${d}',${JSON.stringify(x.id)})" aria-label="Remove">${ic("x",16)}</button></div>`).join("")||`<p class="mut sm-t" style="margin:0 0 4px">Nothing logged. Tap + to add food.</p>`}</div>`}).join("")}
 ${waterCard()}
 <div class="card"><h3>Weekly review</h3>${curTier()=="pro"?`<p style="white-space:pre-wrap">${esc(wsum||"Get an AI review of your last 7 days.")}</p><button class="pri" onclick="weekAI()">Review my week</button>`:`<p class="mut">The weekly AI review unlocks at level ${TIERS.pro.lv} (${rkAtLv(TIERS.pro.lv).n}). Keep earning XP to rank up.</p>`}</div>`};
const rkAtLv=lv=>{let r=0;RANKS.forEach((k,i)=>{if(lv>=k.lv)r=i});return RANKS[r]};
let wsum="";
const delLog=(d,id)=>{S.flog[d]=(S.flog[d]||[]).filter(e=>e.id!=id);go()};
const waterCard=()=>{const k=TD(),w=S.water[k]||0,g=R(S.user.w*35),p=Math.min(100,w/g*100);return `<div class="card water"><div class="ch"><h3>Water</h3><span class="chip ${w>=g?"sel":""}">${w>=g?"Goal reached":R(p)+"%"}</span></div><div class="big">${w}<span class="mut" style="font-size:15px;font-weight:600"> / ${g} ml</span></div><div class="bar2"><div style="width:${p}%;background:var(--ac2)"></div></div><div class="mut sm-t">${w>=g?"Nice, you've hit today's goal.":(g-w)+" ml to go ("+Math.ceil((g-w)/250)+" glasses)"}</div><div class="row"><button class="grow" onclick="drink(-250)" aria-label="Remove 250 ml">− 250</button><button class="pri grow" onclick="drink(250)">${ic("drop",16)} + 250 ml</button></div></div>`};
function drink(n){const k=TD(),b=S.water[k]||0,g=R(S.user.w*35);S.water[k]=Math.max(0,b+n);if(n>0){gain(XPV.water,"water",XPV.waterCap);if(S.water[k]>=g&&!S.water[k+"g"]){S.water[k+"g"]=1;gain(XPV.hydra);cheer("Hydration goal hit! +"+XPV.hydra+" XP","drop")}}else if(b>0)lose(XPV.water,"water");if(S.water[k]<g)delete S.water[k+"g"];go()}
/* ---- food search + portion ---- */
let FM="";
function recentFoods(){const seen=new Set(),out=[];Object.keys(S.flog).sort().reverse().slice(0,21).forEach(d=>(S.flog[d]||[]).slice().reverse().forEach(e=>{if(e.fn&&!seen.has(e.fn)){seen.add(e.fn);out.push(e.fn)}}));return out}
const recKc=r=>mac(r.i).k;
function foodItems(q,f){const fi=(x)=>({id:"f:"+x.n,t:x.n,s:R(x.k)+" kcal per 100 g · P"+x.p+" C"+x.c+" F"+x.f+(x.cu?" · custom":""),r:SERV[x.n]?SERV[x.n][1]:""}),ri=r=>({id:"r:"+r.id,t:r.n,s:"Recipe · "+R(recKc(r))+" kcal per serving",avc:"g"});
 let L=[];
 if(f=="recipes")L=S.recipes.filter(r=>!q||sm(q,r.n)).map(ri);
 else if(f=="recent"){const rf=recentFoods();L=rf.map(n=>F(n)).filter(x=>x&&(!q||sm(q,x.n))).map(fi)}
 else{const pool=S.foods.filter(x=>(f=="all"||!f||x.t==f)&&!(q&&!sm(q,x.n)));
  if(q){const sc=pool.map(x=>({x,s:sm(q,x.n)*(norm(x.n).startsWith(norm(q))?3:1)})).sort((a,b)=>b.s-a.s).map(o=>fi(o.x));L=S.recipes.filter(r=>sm(q,r.n)).map(ri).concat(sc)}
  else{const rf=recentFoods().map(n=>F(n)).filter(Boolean);L=rf.map(fi).concat(pool.filter(x=>!rf.includes(x)).sort((a,b)=>a.n.localeCompare(b.n)).map(fi))}}
 return L}
function openFoodSearch(mt){FM=mt||mealOfTime(new Date().toTimeString().slice(0,5));
 openPicker({title:"Add to "+MTN[FM].toLowerCase(),ph:"Search foods and recipes",items:foodItems,filters:[["all","All"],["recent","Recent"],["recipes","My recipes"],["p","Protein"],["c","Carbs"],["v","Veg and fats"]],keep:true,empty:"No food found. Create it below.",onPick:(id)=>ptOpen(id),create:{label:"Create a custom food",fn:q=>customFood(q)}})}
let PT=null;
function ptOpen(id){if(id.startsWith("r:")){const r=S.recipes.find(x=>x.id==id.slice(2));if(!r)return;PT={kind:"r",r,sv:1,mt:FM,n:r.n}}else{const f=F(id.slice(2));if(!f)return;const sv=SERV[f.n];PT={kind:"f",f,g:sv?sv[0]:100,mt:FM,n:f.n}}pushModal(ptView)}
const ptMac=()=>PT.kind=="r"?(m=>({k:m.k*PT.sv,p:m.p*PT.sv,c:m.c*PT.sv,f:m.f*PT.sv}))(mac(PT.r.i)):kc(PT.f,+PT.g||0);
function ptView(){const o=PT,m=ptMac(),sv=o.kind=="f"&&SERV[o.f.n];
 return mh(esc(o.n),true)+`<div class="card tint tc"><div class="big" id="ptk">${R(m.k)}</div><div class="mut">kcal</div><div id="ptm">${MS(m)}</div></div>`+
 (o.kind=="f"?`<label class="fld gap"><span>Amount (grams)</span><input id="pg" type="number" inputmode="decimal" value="${o.g}" oninput="PT.g=this.value;ptUpd()"></label><div class="chips">${[50,100,150,200,250].map(g=>`<button class="chip" onclick="PT.g=${g};repaintModal()">${g} g</button>`).join("")}${sv?[1,2,3].map(q=>`<button class="chip acc" onclick="PT.g=${sv[0]*q};repaintModal()">${q} ${esc(sv[1])}${q>1?"s":""} (${sv[0]*q} g)</button>`).join(""):""}</div>`
  :`<label class="fld gap"><span>Servings</span><input id="pg" type="number" step="0.25" inputmode="decimal" value="${o.sv}" oninput="PT.sv=+this.value||0;ptUpd()"></label><div class="chips">${[.5,1,1.5,2].map(q=>`<button class="chip" onclick="PT.sv=${q};repaintModal()">${q}×</button>`).join("")}</div>`)+
 `<div class="fld"><span>Meal</span><div class="chips">${MT.map(x=>`<button class="chip ${o.mt==x[0]?"sel":""}" onclick="PT.mt='${x[0]}';repaintModal()">${x[1]}</button>`).join("")}</div></div><button class="pri lg wide" onclick="ptLog()">Add to ${MTN[o.mt].toLowerCase()}</button>`}
function ptUpd(){const m=ptMac();$("ptk").textContent=R(m.k);$("ptm").innerHTML=MS(m)}
function ptLog(){const o=PT,m=ptMac();if(!(m.k>=0)||(o.kind=="f"&&!(+o.g>0))||(o.kind=="r"&&!(o.sv>0)))return toast("Enter an amount first");
 logFood({n:o.kind=="f"?R(+o.g)+"g "+o.f.n:(o.sv==1?"":o.sv+"× ")+o.r.n,...m,s:o.kind=="r"?"recipe":"food",mt:o.mt,fn:o.kind=="f"?o.f.n:null},fdte);if(o.kind=="f"){const l=S.flog[fdte];l[l.length-1].fn=o.f.n}closeModal();toast("Added to "+MTN[o.mt].toLowerCase(),"","check");go()}
let CF={};
function customFood(q){CF={n:(q||"").trim(),k:"",p:"",c:"",f:"",t:"p"};pushModal(cfView)}
const cfView=()=>mh("Create a custom food",true)+`<label class="fld"><span>Food name</span><input value="${esc(CF.n)}" oninput="CF.n=this.value" autofocus></label><p class="mut sm-t">Nutrition per 100 g (check the packet label).</p><div class="row nw"><label class="fld grow"><span>kcal</span><input type="number" inputmode="decimal" value="${esc(CF.k)}" oninput="CF.k=this.value"></label><label class="fld grow"><span>Protein g</span><input type="number" inputmode="decimal" value="${esc(CF.p)}" oninput="CF.p=this.value"></label></div><div class="row nw"><label class="fld grow"><span>Carbs g</span><input type="number" inputmode="decimal" value="${esc(CF.c)}" oninput="CF.c=this.value"></label><label class="fld grow"><span>Fat g</span><input type="number" inputmode="decimal" value="${esc(CF.f)}" oninput="CF.f=this.value"></label></div><button class="pri lg wide" onclick="saveCustomFood()">Save food</button>`;
function saveCustomFood(){const n=CF.n.trim();if(!n)return toast("Name the food");if(!(+CF.k>=0)||CF.k==="")return toast("Enter the calories per 100 g");if(S.foods.some(f=>norm(f.n)==norm(n)))return toast("A food with that name already exists");
 const p=+CF.p||0,c=+CF.c||0,f=+CF.f||0;S.foods.push({n,k:+CF.k,p,c,f,t:p>=15?"p":c>=15?"c":"v",cu:1});popModal();if(PK&&PK.keep){FM=FM||"b";ptOpen("f:"+n)}else{toast("Saved "+n);go()}}
let QA={};
function quickAdd(){QA={n:"",k:"",p:"",c:"",f:"",mt:mealOfTime(new Date().toTimeString().slice(0,5))};openModal(qaView)}
const qaView=()=>mh("Quick add calories")+`<label class="fld"><span>What did you eat?</span><input value="${esc(QA.n)}" oninput="QA.n=this.value" placeholder="e.g. Cafe lunch" autofocus></label><div class="row nw"><label class="fld grow"><span>kcal</span><input type="number" inputmode="numeric" value="${esc(QA.k)}" oninput="QA.k=this.value"></label><label class="fld grow"><span>P g</span><input type="number" inputmode="numeric" value="${esc(QA.p)}" oninput="QA.p=this.value"></label><label class="fld grow"><span>C g</span><input type="number" inputmode="numeric" value="${esc(QA.c)}" oninput="QA.c=this.value"></label><label class="fld grow"><span>F g</span><input type="number" inputmode="numeric" value="${esc(QA.f)}" oninput="QA.f=this.value"></label></div><div class="chips">${MT.map(x=>`<button class="chip ${QA.mt==x[0]?"sel":""}" onclick="QA.mt='${x[0]}';repaintModal()">${x[1]}</button>`).join("")}</div><button class="pri lg wide gap" onclick="if(!QA.n.trim()||!(+QA.k>=0)||QA.k==='')return toast('Add a name and calories');logFood({n:QA.n.trim(),k:+QA.k,p:+QA.p||0,c:+QA.c||0,f:+QA.f||0,s:'manual',mt:QA.mt},fdte);closeModal();go()">Add</button>`;
/* ---- say it / type it: AI estimates and logs ---- */
let AL={};
function aiLogOpen(){AL={text:"",items:[],loading:0,err:"",mt:mealOfTime(new Date().toTimeString().slice(0,5))};openModal(alView)}
function alView(){const o=AL;return mh("Tell Mise what you ate")+(!aiOK()?`<p class="mut">The AI isn’t reachable right now. You can still search for food or use Quick add.</p>`:`<p class="mut">Say or type it in your own words, like “two eggs on toast and a flat white”. Mise estimates the calories and you check them before they’re logged.</p>${o.listening?`<div class="listen"><div class="wv"><i></i><i></i><i></i><i></i><i></i></div><b class="grow">Listening… tap the mic to stop</b></div>`:""}<div class="row nw"><textarea id="alt" rows="3" placeholder="What did you eat?" oninput="AL.text=this.value">${esc(o.text)}</textarea><button class="ibtn lg mic ${o.listening?"rec":""}" id="mic_alt" onclick="voiceStart('alt',false)" aria-label="Speak">${ic("mic",22)}</button></div><div class="chips">${MT.map(x=>`<button class="chip ${o.mt==x[0]?"sel":""}" onclick="AL.mt='${x[0]}';repaintModal()">${x[1]}</button>`).join("")}</div><button class="pri lg wide" onclick="alGo()" ${o.loading?"disabled":""}>${o.loading?'<span class="spin"></span> Estimating':"Estimate calories"}</button>${o.err?`<div class="err">${esc(o.err)}</div>`:""}`)+(o.items.length?`<h3 class="gap2">Check and log</h3>${o.items.map((i,x)=>`<div class="item"><div class="tx"><div class="t">${esc(i.n)}</div><div class="s">~${R(i.g)} g · P${R(i.p)} C${R(i.c)} F${R(i.f)}</div></div><div class="r">${R(i.k)}<span class="mut sm-t"> kcal</span></div><button class="ibtn sm ghost" onclick="AL.items.splice(${x},1);repaintModal()" aria-label="Remove">${ic("x",16)}</button></div>`).join("")}<div class="row gap"><b class="grow">${R(AL.items.reduce((a,i)=>a+i.k,0))} kcal total</b><button class="pri" onclick="alLog()">Log ${AL.items.length} item${AL.items.length>1?"s":""}</button></div>`:"")}
async function alGo(){const t=($("alt")||{}).value||AL.text;AL.text=t;if(!t.trim()){AL.err="Tell me what you ate first.";return repaintModal()}if(!chatLeft()){AL.err="AI limit reached. Resets in "+resetMin()+" min.";return repaintModal()}
 S.use.chat.push(Date.now());AL.loading=1;AL.err="";repaintModal();
 try{const j=pj(await aiCall(`You are a nutritionist. The user says they ate: "${t.replace(/"/g,"'")}". Break this into distinct foods, estimate realistic portion weights in grams if not given, and estimate calories and macros for each. Be realistic, not exaggerated. Reply ONLY with JSON: {"items":[{"name":"","grams":0,"kcal":0,"protein":0,"carbs":0,"fat":0}]}. If it is not food, return {"items":[]}.`,null,true));
  AL.items=(j.items||[]).map(x=>{const o={n:String(x.name||"Food").slice(0,60),g:Math.min(2000,+x.grams||0),k:Math.min(2500,+x.kcal||0),p:Math.min(200,+x.protein||0),c:Math.min(300,+x.carbs||0),f:Math.min(150,+x.fat||0)},mk_=o.p*4+o.c*4+o.f*9;if(mk_>0&&(!o.k||Math.abs(o.k-mk_)/mk_>.35))o.k=R(mk_);return o}).filter(x=>x.k>0);if(!AL.items.length)AL.err="I couldn’t find any food in that. Try rephrasing."}catch(e){S.use.chat.pop();AL.err=aiErrMsg(e)}AL.loading=0;repaintModal()}
function alLog(){AL.items.forEach(i=>logFood({n:i.n,k:i.k,p:i.p,c:i.c,f:i.f,s:"assistant",mt:AL.mt},fdte));closeModal();toast("Logged "+AL.items.length+" item"+(AL.items.length>1?"s":""),"","check");go()}
/* ---- photo ---- */
let est=null;
const PHOTO_PROMPT=`You are a nutritionist. Look at this photo of a meal. Identify each distinct food, estimate realistic portion weights in grams from the visible portion size, and estimate calories and macros for each. Be conservative and realistic, never exaggerated. Reply ONLY with JSON: {"name":"short meal name","confidence":"low|medium|high","items":[{"name":"","grams":0,"kcal":0,"protein":0,"carbs":0,"fat":0}]}. If there is no food in the photo return {"name":"","items":[]}.`;
const photoUsed=()=>S.use.photo[TD()]||0;
function photoOpen(){openModal(()=>mh("Log from a photo")+(!aiOK()?`<p class="mut">Photo logging isn’t available right now. You can still search for food or use Quick add.</p>`:`<p class="mut">Photos used today: ${photoUsed()}/${tier().photo}. Estimates can be off, so check them before logging.</p>${!est?`<div class="row"><label class="btn pri filebtn grow lg">${ic("camera",20)} Take photo<input type="file" accept="image/*" capture="environment" hidden onchange="photoPick(this.files[0]);this.value=''"></label><label class="btn filebtn grow lg">${ic("image",20)} From gallery<input type="file" accept="image/*" hidden onchange="photoPick(this.files[0]);this.value=''"></label></div>`:photoView()}`))}
function photoView(){return `${est.img?`<img class="thumb" src="${est.img}" alt="Your meal">`:""}${est.loading?'<p><span class="spin d"></span> Analysing your meal… this can take a few seconds</p>':est.err?`<div class="err">${esc(est.err)}</div><button onclick="est=null;repaintModal()">Try another photo</button>`:`<input value="${esc(est.name)}" style="width:100%" onchange="est.name=this.value"><span class="chip">${esc(est.conf)} confidence</span>${est.items.map((i,x)=>`<div class="item"><div class="tx"><div class="t">${esc(i.n)}</div><div class="s">~${R(i.g)} g</div></div><b>${R(i.k)}</b><span class="mut sm-t">kcal</span><button class="ibtn sm ghost" onclick="est.items.splice(${x},1);repaintModal()" aria-label="Remove">${ic("x",16)}</button></div>`).join("")}<div class="row"><span class="mut">Portion</span>${sel("pm",[[.5,"½×"],[.75,"¾×"],[1,"1×"],[1.25,"1¼×"],[1.5,"1½×"],[2,"2×"]],est.mult,'onchange="est.mult=+this.value;repaintModal()"')}</div>${MS(est.items.reduce((t,i)=>({k:t.k+i.k*est.mult,p:t.p+i.p*est.mult,c:t.c+i.c*est.mult,f:t.f+i.f*est.mult}),{k:0,p:0,c:0,f:0}))}<div class="row"><button class="pri grow lg" onclick="logEst()">Log this meal</button><button onclick="est=null;closeModal()">Discard</button></div>`}`}
function photoPick(f){if(!f)return;if(!aiOK())return toast("Photo logging isn’t available right now");if(photoUsed()>=tier().photo)return toast("Daily photo limit reached ("+tier().photo+"). Rank up for more.");
 const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const sc=Math.min(1,1024/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.round(im.width*sc);c.height=Math.round(im.height*sc);c.getContext("2d").drawImage(im,0,0,c.width,c.height);const url=c.toDataURL("image/jpeg",.82);est={img:url,loading:1,items:[],name:"",mult:1};repaintModal();photoEst(url.split(",")[1])};im.onerror=()=>toast("Couldn’t read that image");im.src=fr.result};fr.readAsDataURL(f)}
async function photoEst(b64){const d=TD();S.use.photo[d]=photoUsed()+1;try{const j=pj(await aiCall(PHOTO_PROMPT,b64,true));const its=(j.items||[]).map(x=>{const o={n:String(x.name||"Food").slice(0,40),g:Math.min(1500,+x.grams||0),k:Math.min(1800,+x.kcal||0),p:Math.min(150,+x.protein||0),c:Math.min(250,+x.carbs||0),f:Math.min(120,+x.fat||0)},mk_=o.p*4+o.c*4+o.f*9;if(mk_>0&&(!o.k||Math.abs(o.k-mk_)/mk_>.35))o.k=R(mk_);return o}).filter(x=>x.k>0);if(!its.length){S.use.photo[d]--;est.err="I couldn’t spot any food in that photo. Try a closer, well-lit shot."}else{S.use.pt++;est.items=its;est.name=j.name||its.map(i=>i.n).join(", ");est.conf=j.confidence||"medium"}}catch(e){S.use.photo[d]=Math.max(0,photoUsed()-1);est.err=aiErrMsg(e)}est.loading=0;repaintModal()}
function logEst(){const m=est.mult||1,t={k:0,p:0,c:0,f:0};est.items.forEach(i=>{t.k+=i.k;t.p+=i.p;t.c+=i.c;t.f+=i.f});logFood({n:est.name||"Photo meal",k:t.k*m,p:t.p*m,c:t.c*m,f:t.f*m,s:"photo"},fdte);gain(XPV.photo);est=null;closeModal();toast("Logged from photo","","camera");go()}
async function weekAI(){if(!aiOK())return toast("AI isn’t available right now");if(chatLeft()<1)return toast("AI chat limit reached this hour");S.use.chat.push(Date.now());wsum="Reviewing…";go();try{const d=[...Array(7)].map((_,i)=>{const x=dAdd(TD(),i-6);return{date:x,...R2(eaten(x))}});wsum=await aiCall(`You are a supportive nutrition coach. In under 110 words, review this person’s last 7 days of logged intake against their daily targets ${JSON.stringify(R2(tgt()))} (goal: ${S.user.g}). Mention one win and one concrete improvement. Data: ${JSON.stringify(d)}`)}catch(e){S.use.chat.pop();wsum=aiErrMsg(e)}go()}
function logM(x){const s_=scaled(MEALS[x]);logFood({n:MEALS[x][0],...s_.m,s:"meal",mt:MEALS[x][1]=="b"?"b":MEALS[x][1]=="s"?"s":mealOfTime(new Date().toTimeString().slice(0,5))=="b"?"l":mealOfTime(new Date().toTimeString().slice(0,5))},fdte);toast("Logged "+MEALS[x][0],"","check");go()}
function logR(id,mt){const r=S.recipes.find(x=>x.id==id);if(r){logFood({n:r.n,...mac(r.i),s:"recipe",mt:mt||(r.typ=="b"?"b":r.typ=="s"?"s":undefined)},fdte);toast("Logged "+r.n,"","check");go()}}

/* ======================= MEALS ======================= */
const mealSub=k=>{sub.meals=k;go()};
V.shop=()=>shopV();
