let EP={text:"",loading:0,err:"",note:""};
function editPlanOpen(){EP={text:"",loading:0,err:"",note:""};openModal(epView)}
function epView(){return mh("Edit plan by ingredients")+`<p class="mut">Tell Mise what you have and it rewrites the plan around it, keeping each day near ${tgt().k} kcal.</p><div class="row"><button class="soft grow" onclick="kitchenOpenFromPlan()">${ic("leaf",16)} My kitchen (${S.pantry.length} items)</button></div>${S.pantry.length?`<div class="chips" style="flex-wrap:wrap">${S.pantry.slice(0,14).map(n=>`<span class="chip">${esc(n)}</span>`).join("")}${S.pantry.length>14?`<span class="chip">+${S.pantry.length-14}</span>`:""}</div>`:""}<div class="row nw gap"><textarea id="ept" rows="3" placeholder="e.g. I only have chicken, rice and broccoli this week. Swap Wednesday dinner for something vegetarian." oninput="EP.text=this.value">${esc(EP.text)}</textarea><button class="ibtn lg mic" id="mic_ept" onclick="voiceStart('ept',false)" aria-label="Speak">${ic("mic",22)}</button></div><div class="row"><button class="pri grow lg" onclick="epGo(true)" ${EP.loading||!aiOK()?"disabled":""}>${EP.loading?'<span class="spin"></span> Rewriting':ic("sparkles",18)+" Rewrite with AI"}</button></div><div class="row"><button class="grow" onclick="epGo(false)">${ic("bolt",16)} Use my kitchen (no AI)</button></div>${!aiOK()?`<p class="mut sm-t">AI isn’t reachable right now, so only “Use my kitchen” works.</p>`:""}${EP.err?`<div class="err">${esc(EP.err)}</div>`:""}${EP.note?`<div class="okmsg">${esc(EP.note)}</div>`:""}`}
function kitchenOpenFromPlan(){openPicker({push:true,title:"What’s in my kitchen",ph:"Search ingredients",items:(q)=>S.foods.filter(x=>!q||sm(q,x.n)).sort((a,b)=>(q?sm(q,b.n)-sm(q,a.n):0)||a.n.localeCompare(b.n)).map(x=>({id:x.n,t:x.n,s:R(x.k)+" kcal per 100 g"})),multi:true,sel:Object.fromEntries(S.pantry.map(n=>[n,{id:n}])),onDone:ids=>{S.pantry=ids;editPlanOpen()}})}
async function epGo(useAI){EP.err="";EP.note="";const t=($("ept")||{}).value||EP.text;EP.text=t;
 if(!useAI){if(!S.pantry.length&&!t.trim()){EP.err="Add some ingredients to your kitchen first.";return repaintModal()}const n=pantryRework();EP.note=n?"Updated "+n+" meals to use what you have.":"I couldn’t find better matches for those ingredients.";go();return repaintModal()}
 if(!chatLeft()){EP.err="AI limit reached. Resets in "+resetMin()+" min.";return repaintModal()}S.use.chat.push(Date.now());EP.loading=1;repaintModal();
 try{const cur=[...Array(7)].map((_,i)=>"Day "+i+": "+SL.map(s=>{const r=S.recipes.find(x=>x.id==S.plan[i+s]);const ix=r?MEALS.findIndex(m=>m[0]==r.n):-1;return s[0]+"="+(ix>=0?ix:"custom")}).join(", ")).join("\n"),p=`You edit a 7-day meal plan using a recipe book. The user says: "${t.replace(/"/g,"'")||"use what I have"}". Ingredients they have: ${S.pantry.join(", ")||"not listed"}. Diet: ${S.user.diet.join(", ")||"none"}; avoids ${S.user.dis||"nothing"}; target ${tgt().k} kcal/day.
CURRENT PLAN (day index 0-6; b=breakfast l=lunch d=dinner; numbers are recipe ids; "custom" is a recipe not in the book):
${cur}
RECIPE BOOK (id|name|type|kcal|protein):
${bookList()}
Change only meals that need to change to honour the request and prefer recipes whose ingredients the user has. Breakfast slots must use Breakfast recipes; lunch and dinner use Lunch & dinner recipes. Reply ONLY with JSON: {"edits":[{"day":0,"slot":"b|l|d","id":0}],"note":"one short sentence"}`,j=pj(await aiCall(p,null,true));let n=0;(j.edits||[]).slice(0,21).forEach(e=>{const sl={b:"Breakfast",l:"Lunch",d:"Dinner"}[e.slot],id=+e.id,dy=+e.day;if(sl&&dy>=0&&dy<7&&Number.isInteger(id)&&MEALS[id]&&scaled(MEALS[id])&&(MEALS[id][1]=="b")==(sl=="Breakfast")){S.plan[dy+sl]=rcp(id,true);n++}});EP.note=n?(j.note||"Updated "+n+" meals."):"The AI had no changes to make.";if(n)toast("Plan updated","","sparkles")}catch(e){S.use.chat.pop();EP.err=aiErrMsg(e)}EP.loading=0;go();repaintModal()}
function pantryRework(){let n=0;const pt=new Set(S.pantry);[["b","Breakfast"],["m","Lunch"],["m","Dinner"]].forEach(([t,sl])=>{const L=findMeals({t}).filter(o=>o.cov>0).slice(0,14);if(!L.length)return;for(let i=0;i<7;i++){const cur=S.recipes.find(x=>x.id==S.plan[i+sl]);const curCov=cur?cur.i.filter(a=>pt.has(a.f)).length:0;const pick=L[(i+(sl=="Dinner"?3:0))%L.length];if(pick.cov>curCov){S.plan[i+sl]=rcp(pick.x,true);n++}}});if(!S.ps)S.ps=mon();return n}
/* ---- meal prep ---- */
let pbSel={m:[],n:5};
const prepIc=()=>"";
function prepV(){return `<div class="stack"><div class="card tint"><div class="ch"><h2>Batch builder</h2></div><p class="mut">Cook once, eat all week. Pick up to two meals and how many servings to cook.</p><div class="row"><button class="pri grow" onclick="pbOpen()">${ic("plus",18)} New batch</button><button class="grow" onclick="pauto()">${ic("bolt",16)} Suggest for me</button></div>${aiOK()?`<div class="row nw"><input id="pai" placeholder="Ask AI: 2 people, 5 lunches, under 30 min" onkeydown="if(event.key=='Enter')prepAI()"><button class="ibtn mic" id="mic_pai" onclick="voiceStart('pai',true)" aria-label="Speak">${ic("mic",20)}</button><button onclick="prepAI()" ${aiBusy?"disabled":""}>${aiBusy?'<span class="spin d"></span>':"Ask AI"}</button></div>`:""}<p class="mut sm-t" style="margin:0">Rank: ${rank().n} · ${S.batches.length}/${tier().batch>50?"unlimited":tier().batch} batches saved.</p></div>
 ${S.batches.map((b,i)=>{const it=batchItems(b),fish=it.some(x=>["Salmon","Cod","Prawns","Tuna (canned)"].includes(x.f)),fr=it.filter(x=>FRESH.includes(x.f)).map(x=>SHORT(x.f));return `<div class="card"><div class="ch"><h2>Batch ${i+1}: ${esc(bTxt(b))}</h2></div>${b.meals.map(x=>{const s_=scaled(MEALS[x]);return `<div style="margin:4px 0"><b>${esc(MEALS[x][0])}</b> <span class="mut">per serving</span>${MS(s_.m)}</div>`}).join("")}<details class="gap"><summary class="b" style="color:var(--ac)">Shopping amounts and cook-day steps ${ic("chevD",14)}</summary><p class="mut">${it.map(x=>R(x.g)+"g "+esc(SHORT(x.f))).join(" · ")}</p><ol style="padding-left:20px;margin:4px 0">${bSteps(b).map(x=>`<li>${esc(x)}</li>`).join("")}</ol><p class="mut">${fish?"Contains fish: fridge 2 days, freeze the rest.":"Fridge 4 days, freeze the rest."}${fr.length?" Add "+fr.join(", ")+" fresh when serving.":""}</p></details><div class="row"><button class="sm pri" onclick="toast(bPlan(S.batches[${i}],['Lunch','Dinner']));go()">Plan lunch${b.meals.length>1?" + dinner":""}</button><button class="sm" onclick="toast(bPlan(S.batches[${i}],['Dinner','Lunch']));go()">Plan as dinners</button><button class="sm" onclick="toast(bShop(S.batches[${i}]));go()">${ic("cart",14)} Shopping list</button><button class="sm dg" onclick="dbl('pb${b.id}',()=>{S.batches.splice(${i},1);go()})">${cfl("pb"+b.id,"Delete")}</button></div></div>`}).join("")}
 <details class="card"><summary class="ch"><h3>${ic("sparkles",16)} Ask the prep coach</h3>${ic("chevD",16)}</summary><div class="row">${["What should I prep this week?","One batch for the week","How long does food keep?"].map(t=>`<button class="chip" onclick="$('pq').value=this.textContent;psay()">${t}</button>`).join("")}</div><div class="chat" id="pc" style="height:300px">${(S.pchat.filter(c=>c.t||c.p).length?S.pchat.filter(c=>c.t||c.p):[{r:"a",t:PH}]).map((c,i,a)=>bub(c,i==a.length-1)).join("")}</div><div class="composer"><input id="pq" placeholder="Ask anything about meal prep" onkeydown="if(event.key=='Enter')psay()"><button class="pri" onclick="psay()" ${busy?"disabled":""} aria-label="Send">${ic("send",20)}</button></div></details></div>`}
const PH="**Meal-prep assistant**\nAsk me anything about batch cooking. I can build a prep plan around your goal and diet, create a batch, and add the shopping list.\n- “What should I prep this week?”\n- “One batch for the week”\n- “Prep dinners for 2 people on a budget”";
function pbOpen(){pbSel={m:[],n:5};openModal(pbView)}
const pbView=()=>mh("New batch")+`<p class="mut">Choose up to two meals.</p>${pbSel.m.map((x,i)=>`<div class="item"><div class="tx"><div class="t">${esc(MEALS[x][0])}</div></div><button class="ibtn sm ghost" onclick="pbSel.m.splice(${i},1);repaintModal()" aria-label="Remove">${ic("x",16)}</button></div>`).join("")}${pbSel.m.length<2?`<button class="soft wide" onclick="pbPick()">${ic("search",18)} Search meals</button>`:""}<label class="fld gap"><span>Servings of each (1 to 21)</span><input type="number" min="1" max="21" value="${pbSel.n}" oninput="pbSel.n=+this.value||1"></label><button class="pri lg wide" onclick="pbMake()">Create batch</button>`;
function pbPick(){openPicker({push:true,title:"Choose a meal",ph:"Search meals",items:(q,f)=>findMeals({q,t:f=="all"?"all":f,tags:f=="prepf"?["prep"]:[]}).slice(0,80).map(o=>({id:o.x,t:o.m[0],s:TY[o.m[1]]+" · "+R(o.s.m.k)+" kcal"+((tagsOf(o.m).includes("prep"))?" · keeps well":"")})),filters:[["prepf","Good for prep"],["all","All"],["m","Lunch & dinner"],["b","Breakfast"]],f:"prepf",onPick:id=>{if(!pbSel.m.includes(+id))pbSel.m.push(+id);repaintModal()}});PK.f="prepf"}
function pbMake(){if(!pbSel.m.length)return toast("Choose at least one meal");const r=mkBatch(pbSel.m,Math.min(21,Math.max(1,pbSel.n)));if(!r)return toast("Your "+rank().n+" rank holds "+tier().batch+" saved batch. Delete it, or rank up to unlock more.");gain(XPV.batch);closeModal();toast("Batch created","","layers");go()}
function pauto(){const r=pickPrep("m",2);if(!r.length)return toast("No prep-friendly meals fit your diet");const b=mkBatch(r.map(o=>o.x),5);if(!b)return toast("Your "+rank().n+" rank holds "+tier().batch+" saved batch.");toast("Batch created","","layers");go()}
async function prepAI(){if(!aiOK()||aiBusy)return;const q=(($("pai")||{}).value||"").trim()||"a sensible batch for my week";if(!chatLeft())return toast("AI limit reached. Resets in "+resetMin()+" min.");S.use.chat.push(Date.now());aiBusy=1;go();
 try{const t=tgt(),u=S.user,p=`You are a meal-prep coach choosing recipes to batch cook. Request: "${q.replace(/"/g,"'")}". Goal ${u.g}; daily target ${t.k} kcal, ${t.p} g protein; diet ${u.diet.join(", ")||"none"}; avoids ${u.dis||"nothing"}. Pick 1 or 2 recipe ids from the book that keep well and suit the request, and a number of servings (1-14).
RECIPE BOOK (id|name|type|kcal|protein):
${bookList()}
Reply ONLY with JSON: {"ids":[0],"servings":5,"why":"one short sentence"}`,j=pj(await aiCall(p,null,true)),ids=(j.ids||[]).map(Number).filter(x=>Number.isInteger(x)&&MEALS[x]&&scaled(MEALS[x])).slice(0,2);if(!ids.length)throw new Error("no valid recipes");const b=mkBatch(ids,+j.servings||5);toast(b?(j.why||"Batch created"):"Your "+rank().n+" rank holds "+tier().batch+" saved batch. Delete one or rank up.")}catch(e){S.use.chat.pop();toast(aiErrMsg(e).slice(0,140))}aiBusy=0;go()}
/* ---- shopping ---- */
let shv="list";
function itm(x,k,val){CL().items[x][k]=k=="pr"?+val||0:k=="l"?nl(val):val;go()}
function delL(id){S.lists=S.lists.filter(l=>l.id!=id);if(!S.lists.length)S.lists.push({id:Date.now(),name:"Groceries",budget:100,items:[]});li=S.lists[0].id;go()}
function shopV(){const L=CL();li=L.id;const tot=L.items.reduce((a,i)=>a+i.pr,0),ov=tot>L.budget,left=L.items.filter(i=>!i.d).length;
 const tabs=`<div class="chips">${S.lists.map(l=>`<button class="chip ${l.id==li?"sel":""}" onclick="li=${l.id};go()">${esc(l.name)}</button>`).join("")}<button class="chip" onclick="newList()">${ic("plus",12)} New list</button><button class="chip ${shv=="hist"?"sel":""}" onclick="shv='${shv=="hist"?"list":"hist"}';go()">History (${S.shist.length})</button></div>`;
 if(shv=="hist")return tabs+`<div class="card"><div class="ch"><h2>Shopping history</h2>${S.shist.length?`<button class="sm dg" onclick="dbl('cs',()=>{S.shist=[];go()})">${cfl("cs","Clear")}</button>`:""}</div>${S.shist.map(h=>`<div class="item"><div class="tx"><div class="t">${fd(h.d)} · ${esc(h.list)}</div><div class="s">${h.items.length} items · $${h.total.toFixed(2)}</div><div class="s">${h.items.map(i=>esc(i.n)).join(", ")}</div></div><button class="sm" onclick="reAddH(${h.id})">Add again</button></div>`).join("")||empty("doc","No shopping history yet. Tick items as purchased, then press Finish shopping.")}</div>`;
 return tabs+`<div class="grid g2"><div class="card"><div class="ch"><h2>${esc(L.name)}</h2><span class="mut sm-t">${left} to buy</span></div><div class="row nw"><span class="mut">Budget $</span><input type="number" value="${L.budget}" onchange="CL().budget=+this.value;go()" style="max-width:110px"><button class="sm dg" onclick="dbl('dl',()=>delL(${L.id}))">${cfl("dl","Delete list")}</button></div><div class="bar2 ${ov?"over":""}"><div style="width:${Math.min(100,L.budget?tot/L.budget*100:0)}%"></div></div><p ${ov?'style="color:var(--rd)"':'class="mut"'}><b>$${tot.toFixed(2)}</b> of $${L.budget} · ${ov?"over by $"+(tot-L.budget).toFixed(2):"$"+(L.budget-tot).toFixed(2)+" left"}</p></div>
 <div class="card"><h3>Add an item</h3><button class="soft wide" onclick="shopPick()">${ic("search",18)} Search foods and ingredients</button><div class="row nw gap"><input id="sn" placeholder="Or type an item" onkeydown="if(event.key=='Enter')addI()"><input id="sq" placeholder="Qty" style="flex:0 0 80px"><input id="sp" type="number" placeholder="$" style="flex:0 0 70px"><button class="pri" onclick="addI()" aria-label="Add">${ic("plus",18)}</button></div></div></div>
 <div class="card"><div class="ch"><h2>Items</h2></div><div class="row"><button class="sm" onclick="CL().items.forEach(i=>i.d=1);go()">Mark all bought</button><button class="sm pri" onclick="finishShop()">Finish shopping</button><button class="sm dg" onclick="dbl('ci',()=>{CL().items=[];go()})">${cfl("ci","Delete all")}</button></div>${L.items.map((i,x)=>i.e?`<div class="item" style="flex-wrap:wrap"><input value="${esc(i.n)}" onchange="itm(${x},'n',this.value)" style="flex:2 1 120px"><input value="${esc(i.q)}" placeholder="Qty" onchange="itm(${x},'q',this.value)" style="flex:1 1 60px"><input type="number" value="${i.pr}" onchange="itm(${x},'pr',this.value)" style="flex:1 1 70px"><input value="${esc(i.l)}" placeholder="Store link" onchange="itm(${x},'l',this.value)" style="flex:3 1 160px"><button class="sm pri" onclick="CL().items[${x}].e=0;go()">Done</button></div>`:`<div class="item"><input type="checkbox" ${i.d?"checked":""} onchange="CL().items[${x}].d=this.checked;go()" aria-label="Bought"><div class="tx" style="${i.d?"text-decoration:line-through;opacity:.5":""}"><div class="t">${esc(i.n)}</div><div class="s">${esc(i.q)}</div></div><b>$${i.pr.toFixed(2)}</b>${/^https?:\/\//.test(i.l)?`<a class="btn sm pri" href="${esc(i.l)}" target="_blank" rel="noopener noreferrer">${ic("ext",14)}</a>`:""}<button class="ibtn sm ghost" onclick="CL().items[${x}].e=1;go()" aria-label="Edit">${ic("edit",16)}</button><button class="ibtn sm ghost" onclick="CL().items.splice(${x},1);go()" aria-label="Remove">${ic("x",16)}</button></div>`).join("")||empty("cart","This list is empty. Add your first item above.")}</div>`}
function newList(){openModal(()=>mh("New shopping list")+`<label class="fld"><span>List name</span><input id="ln" placeholder="e.g. Weekend BBQ" autofocus></label><label class="fld"><span>Budget ($)</span><input id="lb" type="number" inputmode="decimal" placeholder="100"></label><button class="pri lg wide" onclick="S.lists.push({id:Date.now(),name:v('ln')||'List',budget:+v('lb')||0,items:[]});li=S.lists.at(-1).id;closeModal();go()">Create list</button>`)}
function shopPick(){openPicker({title:"Add to "+CL().name,ph:"Search foods and ingredients",items:(q)=>S.foods.filter(x=>!q||sm(q,x.n)).sort((a,b)=>(q?sm(q,b.n)-sm(q,a.n):0)||a.n.localeCompare(b.n)).map(x=>({id:x.n,t:x.n,s:R(x.k)+" kcal per 100 g"})),multi:true,onDone:ids=>{const L=CL();ids.forEach(n=>L.items.push({n,q:"",pr:0,l:"",d:0}));toast("Added "+ids.length+" item"+(ids.length>1?"s":""),"","cart");go()}})}
function addI(){const n=v("sn").trim();if(!n)return toast("Name the item");CL().items.push({n:cap(n),q:v("sq"),pr:+v("sp")||0,l:"",d:0});go()}
function finishShop(){const L=CL(),done=L.items.filter(i=>i.d);if(!done.length)return toast("Tick the items you bought first (or press Mark all bought)");S.shist.unshift({id:Date.now(),d:TD(),list:L.name,items:done.map(i=>({n:i.n,q:i.q,pr:i.pr})),total:done.reduce((a,i)=>a+i.pr,0)});S.shist=S.shist.slice(0,60);L.items=L.items.filter(i=>!i.d);toast("Moved "+done.length+" items to your shopping history");go()}
function reAddH(id){const h=S.shist.find(x=>x.id==id);if(!h)return;const L=CL();h.items.forEach(i=>L.items.push({n:i.n,q:i.q,pr:i.pr,l:"",d:0}));toast("Added "+h.items.length+" items to "+L.name);shv="list";go()}
